        /// </remarks>
        /// <param name="text">
        /// Text to be checked
        /// </param>
        /// <returns>
        /// True if the <paramref name="text" /> conforms to the pattern
        /// </returns>
        public static bool MatchesXsDate(string text)
        {
            return RegexMatchesXsDate.IsMatch(text);
        }

        /// <summary>
        /// Check that the <paramref name="year" /> of an <c>xs:date</c> is a leap year.
        /// </summary>
        /// <remarks>
        /// <para>
        /// The <paramref name="year" /> is expected to be given as text, <em>i.e.</em>, as digits with
        /// an optional minus prefix, as the year can be arbitrarily large.
        /// </para>
        /// <para>
        /// We consider the years B.C. to be one-off. See the note at
        /// https://www.w3.org/TR/xmlschema-2/#dateTime: "'-0001' is the lexical
        /// representation of the year 1 Before Common Era (1 BCE, sometimes written "1 BC")."
        /// Hence, the year -1 in XML is the year 0 in astronomical years.
        /// </para>
        /// </remarks>
        /// <param name="year">
        /// Text of the year to be checked
        /// </param>
        /// <returns>
        /// True if the <paramref name="year" /> is a leap year
        /// </returns>
        internal static bool IsLeapYear(
            string year
        )
        {
            long remainder = (
                Common.FloorMod(Common.ParseSafeInt(Common.StringHelpers.Slice(Common.StringHelpers.LStrip(year, "-"), -4)), 400));
            if (year.StartsWith("-", System.StringComparison.Ordinal))
            {
                remainder = Common.FloorMod(remainder + 399, 400);
            }
            return (Common.FloorMod(remainder, 4)) == (0)
            && (
                (Common.FloorMod(remainder, 100)) != (0)
                || remainder == 0
            );
        }  // internal static bool IsLeapYear

        /// <summary>
        /// Check that the <paramref name="day" /> exists in the <paramref name="month" />.
        /// </summary>
        /// <param name="is_leap_year">
        /// True if February has 29 days
        /// </param>
        /// <param name="month">
        /// Month of the year, starting with 1
        /// </param>
        /// <param name="day">
        /// Day of the month, starting with 1
        /// </param>
        /// <returns>
        /// True if the <paramref name="day" /> exists in the <paramref name="month" />
        /// </returns>
        internal static bool IsDayOfMonthValid(
            bool isLeapYear,
            long month,
            long day
        )
        {
            if (
                month < 1
                || month > 12
                || day < 1
            )
            {
                return false;
            }
            if (month == 2)
            {
                if (isLeapYear)
                {
                    return day <= 29;
                }
                return day <= 28;
            }
            switch (month)
            {
                case 4:
                case 6:
                case 9:
                case 11:
                    return day <= 30;
            }
            return day <= 31;
        }  // internal static bool IsDayOfMonthValid

        /// <summary>
        /// Check that the date at the start of <paramref name="text" /> is valid.
        /// </summary>
        /// <remarks>
        /// The <paramref name="text" /> is expected to start with a date matching the pattern
        /// <c>-?YYYY-MM-DD</c>, where the year can have more than four digits. Whatever follows
        /// the date, such as the time or the time zone, is ignored.
        /// </remarks>
        /// <param name="text">
        /// Text to be checked
        /// </param>
        /// <returns>
        /// True if the date at the start of <paramref name="text" /> is valid
        /// </returns>
        internal static bool IsPrefixValidDate(
            string text
        )
        {
            long monthStart = Common.StringHelpers.Find(text, "-", 1) + 1;
            var year = (
                Common.StringHelpers.Slice(text, 0, monthStart - 1));
            if (Common.StringHelpers.LStrip(Common.StringHelpers.LStrip(year, "-"), "0") == "")
            {
                return false;
            }
            long month = (
                Common.ParseSafeInt(Common.StringHelpers.Slice(text, monthStart, monthStart + 2)));
            long day = (
                Common.ParseSafeInt(Common.StringHelpers.Slice(text, monthStart + 3, monthStart + 5)));
            return (
                Verification.IsDayOfMonthValid(Verification.IsLeapYear(year), month, day));
        }  // internal static bool IsPrefixValidDate

        /// <summary>
        /// Check that <paramref name="text" /> is a valid <c>xs:date</c>.
        /// </summary>
        /// <remarks>
        /// <para>
        /// We check that the <paramref name="text" /> matches the pattern of <c>xs:date</c>, and that
        /// the day exists in the month (<em>e.g.</em>, February 29th only in leap years).
        /// </para>
        /// <para>
        /// See: https://www.w3.org/TR/xmlschema-2/#date
        /// </para>
        /// </remarks>
        /// <param name="text">
        /// Text to be checked
        /// </param>
        /// <returns>
        /// True if the <paramref name="text" /> is a valid <c>xs:date</c>
        /// </returns>
        public static bool IsXsDate(
            string text
        )
        {
            return Verification.MatchesXsDate(text)
            && Verification.IsPrefixValidDate(text);
        }  // public static bool IsXsDate

        [CodeAnalysis.SuppressMessage("ReSharper", "InconsistentNaming")]
        [CodeAnalysis.SuppressMessageAttribute("ReSharper", "IdentifierTypo")]
        [CodeAnalysis.SuppressMessage("ReSharper", "StringLiteralTypo")]
        private static Regex _constructMatchesXsDateTime()
        {
            var digit = "[0-9]";
            var yearFrag = $"-?(([1-9]{digit}{digit}{digit}+)|(0{digit}{digit}{digit}))";
            var monthFrag = "((0[1-9])|(1[0-2]))";
            var dayFrag = $"((0[1-9])|([12]{digit})|(3[01]))";
            var hourFrag = $"(([01]{digit})|(2[0-3]))";
            var minuteFrag = $"[0-5]{digit}";
            var secondFrag = $"([0-5]{digit})(\\.{digit}+)?";
            var endOfDayFrag = "24:00:00(\\.0+)?";
            var timezoneFrag = $"(Z|(\\+|-)((0{digit}|1[0-3]):{minuteFrag}|14:00))";
            var dateTimeLexicalRep = $"{yearFrag}-{monthFrag}-{dayFrag}T(({hourFrag}:{minuteFrag}:{secondFrag})|{endOfDayFrag}){timezoneFrag}?";
            var pattern = $"^{dateTimeLexicalRep}$";

            return new Regex(pattern);
        }

        private static readonly Regex RegexMatchesXsDateTime = _constructMatchesXsDateTime();

        /// <summary>
        /// Check that <paramref name="text" /> conforms to the pattern of an <c>xs:dateTime</c>.
        /// </summary>
        /// <remarks>
        /// See: https://www.w3.org/TR/xmlschema-2/#dateTime
        /// </remarks>
        /// <param name="text">
        /// Text to be checked
        /// </param>
        /// <returns>
        /// True if the <paramref name="text" /> conforms to the pattern
        /// </returns>
        public static bool MatchesXsDateTime(string text)
        {
            return RegexMatchesXsDateTime.IsMatch(text);
        }

        /// <summary>
        /// Check that <paramref name="text" /> is a <c>xs:dateTime</c>.
        /// </summary>
        /// <remarks>
        /// <para>
        /// The <c>text</c> is assumed to match a pre-defined pattern for <c>xs:dateTime</c>.
        /// In this function, we check for days of month (e.g., February 29th).
        /// </para>
        /// <para>
        /// See: https://www.w3.org/TR/xmlschema-2/#dateTime
        /// </para>
        /// </remarks>
        /// <param name="text">
        /// Text to be checked
        /// </param>
        /// <returns>
        /// True if the <paramref name="text" /> is a valid <c>xs:dateTime</c>
        /// </returns>
        public static bool IsXsDateTime(
            string text
        )
        {
            return Verification.MatchesXsDateTime(text)
            && Verification.IsPrefixValidDate(text);
        }  // public static bool IsXsDateTime

        /// <summary>
        /// Get the digits of the fraction of a second in <paramref name="text" />.
        /// </summary>
        /// <remarks>
        /// The <paramref name="text" /> is expected to be a valid <c>xs:dateTime</c> with the time
        /// zone fixed to UTC, <em>i.e.</em>, it ends with <c>Z</c>, <c>+00:00</c> or <c>-00:00</c>.
        /// </remarks>
        /// <param name="text">
        /// Date-time to be parsed
        /// </param>
        /// <returns>
        /// The digits after the decimal point, or an empty text if there are none
        /// </returns>
        internal static string FractionOfDateTimeUtc(
            string text
        )
        {
            long point = Common.StringHelpers.Find(text, ".");
            if (point == -1)
            {
                return "";
            }
            if (text.EndsWith("Z", System.StringComparison.Ordinal))
            {
                return Common.StringHelpers.Slice(text, point + 1, -1);
            }
            return Common.StringHelpers.Slice(text, point + 1, -6);
        }  // internal static string FractionOfDateTimeUtc

        /// <summary>
        /// Check that the date of <paramref name="nextText" /> is the day after the date of
        /// <paramref name="text" />.
        /// </summary>
        /// <remarks>
        /// Both <paramref name="text" /> and <paramref name="nextText" /> are expected to start with
        /// a valid date matching the pattern <c>-?YYYY-MM-DD</c>, where the year can have
        /// more than four digits, but has to fit into an integer. Whatever follows
        /// the date, such as the time or the time zone, is ignored.
        /// </remarks>
        /// <param name="text">
        /// Text starting with the date to be incremented
        /// </param>
        /// <param name="next_text">
        /// Text starting with the date expected to follow
        /// </param>
        /// <returns>
        /// True if the date of <paramref name="nextText" /> follows the date of
        /// <paramref name="text" />
        /// </returns>
        internal static bool IsNextDay(
            string text,
            string nextText
        )
        {
            long monthStart = Common.StringHelpers.Find(text, "-", 1) + 1;
            long nextMonthStart = Common.StringHelpers.Find(nextText, "-", 1) + 1;
            var yearText = (
                Common.StringHelpers.Slice(text, 0, monthStart - 1));
            long year = Common.ParseSafeInt(yearText);
            long month = (
                Common.ParseSafeInt(Common.StringHelpers.Slice(text, monthStart, monthStart + 2)));
            long day = (
                Common.ParseSafeInt(Common.StringHelpers.Slice(text, monthStart + 3, monthStart + 5)));
            long nextYear = (
                Common.ParseSafeInt(Common.StringHelpers.Slice(nextText, 0, nextMonthStart - 1)));
            long nextMonth = (
                Common.ParseSafeInt(Common.StringHelpers.Slice(nextText, nextMonthStart, nextMonthStart + 2)));
            long nextDay = (
                Common.ParseSafeInt(Common.StringHelpers.Slice(nextText, nextMonthStart + 3, nextMonthStart + 5)));
            if (Verification.IsDayOfMonthValid(Verification.IsLeapYear(yearText), month, day + 1))
            {
                return year == nextYear
                && month == nextMonth
                && (day + 1) == (nextDay);
            }
            if (nextDay != 1)
            {
                return false;
            }
            if (month < 12)
            {
                return year == nextYear
                && (month + 1) == (nextMonth);
            }
            return nextMonth == 1
            && (
                (nextYear) == (year + 1)
                || (
                    year == -1
                    && nextYear == 1
                )
            );
        }  // internal static bool IsNextDay

        /// <summary>
        /// Check that the date-time <paramref name="that" /> is before <paramref name="other" />.
        /// </summary>
        /// <remarks>
        /// <para>
        /// We compare the years as integers, and the rest of the texts part by part as
        /// strings, since the fraction of a second can be arbitrarily long.
        /// </para>
        /// <para>
        /// We do not compare the years with more than 15 digits, as they do not safely fit
        /// into an integer. Such years are valid in <c>xs:dateTime</c>, but not realistic.
        /// </para>
        /// <para>
        /// The end of a day, <c>24:00:00</c>, is the same instant as the start of the next day,
        /// see the note at https://www.w3.org/TR/xmlschema-2/#dateTime.
        /// </para>
        /// </remarks>
        /// <param name="that">
        /// Date-time which is expected to come first
        /// </param>
        /// <param name="other">
        /// Date-time which is expected to come later
        /// </param>
        /// <returns>
        /// True if <paramref name="that" /> is before <paramref name="other" />, False if not, and
        /// None if either of them is not a valid <c>xs:dateTime</c> in UTC, or if
        /// either of their years has more than 15 digits
        /// </returns>
        public static bool? DateTimeUtcLess(
            string that,
            string other
        )
        {
            if (
                !Verification.IsXsDateTimeUtc(that)
                || (!Verification.IsXsDateTimeUtc(other))
            )
            {
                return null;
            }
            long thatMonthStart = Common.StringHelpers.Find(that, "-", 1) + 1;
            long otherMonthStart = Common.StringHelpers.Find(other, "-", 1) + 1;
            var thatYearText = (
                Common.StringHelpers.Slice(that, 0, thatMonthStart - 1));
            var otherYearText = (
                Common.StringHelpers.Slice(other, 0, otherMonthStart - 1));
            if (
                Common.StringHelpers.Len(Common.StringHelpers.LStrip(thatYearText, "-")) > 15
                || Common.StringHelpers.Len(Common.StringHelpers.LStrip(otherYearText, "-")) > 15
            )
            {
                return null;
            }
            long thatYear = Common.ParseSafeInt(thatYearText);
            long otherYear = Common.ParseSafeInt(otherYearText);
            var thatRest = (
                Common.StringHelpers.Slice(that, thatMonthStart, thatMonthStart + 14));
            var otherRest = (
                Common.StringHelpers.Slice(other, otherMonthStart, otherMonthStart + 14));
            var thatFraction = (
                Common.StringHelpers.RStrip(Verification.FractionOfDateTimeUtc(that), "0"));
            var otherFraction = (
                Common.StringHelpers.RStrip(Verification.FractionOfDateTimeUtc(other), "0"));
            var less = false;
            if (thatYear != otherYear)
            {
                less = thatYear < otherYear;
            }
            else if (thatRest != otherRest)
            {
                less = (
                    Common.StringHelpers.CompareByCodePoints(thatRest, otherRest) < 0);
            }
            else
            {
                less = (
                    Common.StringHelpers.CompareByCodePoints(thatFraction, otherFraction) < 0);
            }
            if (
                less
                && Common.StringHelpers.Slice(that, thatMonthStart + 6, thatMonthStart + 8) == "24"
                && Common.StringHelpers.Slice(other, otherMonthStart + 6, otherMonthStart + 14) == "00:00:00"
                && otherFraction == ""
            )
            {
                return !Verification.IsNextDay(that, other);
            }
            return less;
        }  // public static bool? DateTimeUtcLess

        /// <summary>
        /// Check that the date-time <paramref name="that" /> is before <paramref name="other" />, unless
        /// either of them is invalid.
        /// </summary>
        /// <remarks>
        /// The invalid date-times are reported by the invariants of
        /// <see cref="Our.DateTimeUtc" />, so that we do not report them twice.
        /// See <see cref="Our.Verification.DateTimeUtcLess" />.
        /// </remarks>
        /// <param name="that">
        /// Date-time which is expected to come first
        /// </param>
        /// <param name="other">
        /// Date-time which is expected to come later
        /// </param>
        /// <returns>
        /// True if <paramref name="that" /> is before <paramref name="other" />, or if either of
        /// them is not a valid <c>xs:dateTime</c> in UTC
        /// </returns>
        public static bool DateTimeUtcLessOrInvalid(
            string that,
            string other
        )
        {
            var less = Verification.DateTimeUtcLess(that, other);
            if (less == null)
            {
                return true;
            }
            return less.Value;
        }  // public static bool DateTimeUtcLessOrInvalid

        [CodeAnalysis.SuppressMessage("ReSharper", "InconsistentNaming")]
        [CodeAnalysis.SuppressMessageAttribute("ReSharper", "IdentifierTypo")]
        [CodeAnalysis.SuppressMessage("ReSharper", "StringLiteralTypo")]
        private static Regex _constructMatchesXsDecimal()
        {
            var digit = "[0-9]";
            var unsignedNoDecimalPtNumeral = $"{digit}+";
            var noDecimalPtNumeral = $"(\\+|-)?{unsignedNoDecimalPtNumeral}";
            var fracFrag = $"{digit}+";
            var unsignedDecimalPtNumeral = $"({unsignedNoDecimalPtNumeral}\\.{fracFrag}|\\.{fracFrag})";
            var decimalPtNumeral = $"(\\+|-)?{unsignedDecimalPtNumeral}";
            var decimalLexicalRep = $"({decimalPtNumeral}|{noDecimalPtNumeral})";
            var pattern = $"^{decimalLexicalRep}$";

            return new Regex(pattern);
        }

        private static readonly Regex RegexMatchesXsDecimal = _constructMatchesXsDecimal();

        /// <summary>
        /// Check that <paramref name="text" /> conforms to the pattern of an <c>xs:decimal</c>.
        /// </summary>
