        /// <summary>
        /// Check that the number given as <paramref name="digits" /> is at most <paramref name="limit" />.
        /// </summary>
        /// <remarks>
        /// <para>
        /// Both <paramref name="digits" /> and <paramref name="limit" /> are expected to be decimal digits
        /// without a sign and without leading zeros. An empty text represents zero.
        /// </para>
        /// <para>
        /// We compare the numbers as strings, since they might not fit into an integer.
        /// The digits of numbers of equal length are ordered as the numbers themselves.
        /// </para>
        /// </remarks>
        /// <param name="digits">
        /// Number to be checked
        /// </param>
        /// <param name="limit">
        /// Largest allowed number
        /// </param>
        /// <returns>
        /// True if <paramref name="digits" /> is at most <paramref name="limit" />
        /// </returns>
        internal static bool IsMagnitudeAtMost(
            string digits,
            string limit
        )
        {
            if (Common.StringHelpers.Len(digits) != Common.StringHelpers.Len(limit))
            {
                return (
                    Common.StringHelpers.Len(digits) < Common.StringHelpers.Len(limit));
            }
            return (
                Common.StringHelpers.CompareByCodePoints(digits, limit) <= 0);
        }  // internal static bool IsMagnitudeAtMost

        /// <summary>
        /// Check that the integer <paramref name="text" /> is within the given range.
        /// </summary>
        /// <remarks>
        /// The <paramref name="text" /> is expected to consist of decimal digits with an optional
        /// sign.
        /// </remarks>
        /// <param name="text">
        /// Text to be checked
        /// </param>
        /// <param name="max_negative">
        /// Largest allowed magnitude of a negative number
        /// </param>
        /// <param name="max_positive">
        /// Largest allowed positive number
        /// </param>
        /// <returns>
        /// True if the <paramref name="text" /> is within the range
        /// </returns>
        internal static bool IsIntegerInRange(
            string text,
            string maxNegative,
            string maxPositive
        )
        {
            var digits = (
                Common.StringHelpers.LStrip(Common.StringHelpers.LStrip(text, "+-"), "0"));
            if (text.StartsWith("-", System.StringComparison.Ordinal))
            {
                return (
                    Verification.IsMagnitudeAtMost(digits, maxNegative));
            }
            return (
                Verification.IsMagnitudeAtMost(digits, maxPositive));
        }  // internal static bool IsIntegerInRange

        /// <summary>
        /// Check that the magnitude of the decimal <paramref name="text" /> is below <paramref name="limit" />.
        /// </summary>
        /// <remarks>
        /// <para>
        /// The <paramref name="text" /> is expected to match the pattern of a finite <c>xs:double</c>
        /// or <c>xs:float</c>, <em>i.e.</em>, a decimal with an optional sign, an optional point and
        /// an optional exponent. The <paramref name="limit" /> is expected to be a positive integer
        /// without leading zeros.
        /// </para>
        /// <para>
        /// We compare the numbers as strings, since they do not necessarily fit into
        /// any native number, and parsing them to floating-point numbers would round them.
        /// </para>
        /// </remarks>
        /// <param name="text">
        /// Decimal to be checked
        /// </param>
        /// <param name="limit">
        /// Exclusive upper bound on the magnitude
        /// </param>
        /// <returns>
        /// True if the magnitude of <paramref name="text" /> is below <paramref name="limit" />
        /// </returns>
        internal static bool IsDecimalMagnitudeBelow(
            string text,
            string limit
        )
        {
            var unsigned = Common.StringHelpers.LStrip(text, "+-");
            long exponentStart = Common.StringHelpers.Find(unsigned, "e");
            if (exponentStart == -1)
            {
                exponentStart = Common.StringHelpers.Find(unsigned, "E");
            }
            var mantissa = unsigned;
            var exponentText = "";
            if (exponentStart != -1)
            {
                mantissa = (
                    Common.StringHelpers.Slice(unsigned, 0, exponentStart));
                exponentText = (
                    Common.StringHelpers.Slice(unsigned, exponentStart + 1));
            }
            long point = Common.StringHelpers.Find(mantissa, ".");
            var integerPart = mantissa;
            var fractionPart = "";
            if (point != -1)
            {
                integerPart = Common.StringHelpers.Slice(mantissa, 0, point);
                fractionPart = Common.StringHelpers.Slice(mantissa, point + 1);
            }
            var head = Common.StringHelpers.LStrip(integerPart, "0");
            var tail = fractionPart;
            long shift = Common.StringHelpers.Len(head);
            if (head == "")
            {
                tail = Common.StringHelpers.LStrip(fractionPart, "0");
                if (tail == "")
                {
                    return true;
                }
                shift = (
                    Common.StringHelpers.Len(tail) - Common.StringHelpers.Len(fractionPart));
            }
            var exponentDigits = (
                Common.StringHelpers.LStrip(Common.StringHelpers.LStrip(exponentText, "+-"), "0"));
            if (Common.StringHelpers.Len(exponentDigits) > 15)
            {
                return (
                    exponentText.StartsWith("-", System.StringComparison.Ordinal));
            }
            long exponent = 0;
            if (Common.StringHelpers.Len(exponentDigits) > 0)
            {
                exponent = Common.ParseSafeInt(exponentDigits);
                if (exponentText.StartsWith("-", System.StringComparison.Ordinal))
                {
                    exponent = -exponent;
                }
            }
            long magnitude = exponent + shift;
            if (magnitude != Common.StringHelpers.Len(limit))
            {
                return magnitude < Common.StringHelpers.Len(limit);
            }
            return (
                Common.StringHelpers.CompareByCodePoints(head + tail, limit) < 0);
        }  // internal static bool IsDecimalMagnitudeBelow

        /// <summary>
        /// Check that <paramref name="text" /> is a valid <c>xs:double</c>.
        /// </summary>
        /// <remarks>
        /// <para>
        /// We check that the <paramref name="text" /> matches the pattern of <c>xs:double</c>, and
        /// that it does not overflow, <em>i.e.</em>, that it does not round to infinity unless it
        /// is <c>INF</c> or <c>-INF</c>. See <see cref="Our.Constants.XsDoubleOverflowThreshold" />.
        /// </para>
        /// <para>
        /// See: https://www.w3.org/TR/xmlschema-2/#double
        /// </para>
        /// </remarks>
        /// <param name="text">
        /// Text to be checked
        /// </param>
        /// <returns>
        /// True if the <paramref name="text" /> is a valid <c>xs:double</c>
        /// </returns>
        public static bool IsXsDouble(
            string text
        )
        {
            if (!Verification.MatchesXsDouble(text))
            {
                return false;
            }
            switch (text)
            {
                case "INF":
                case "-INF":
                case "NaN":
                    return true;
            }
            return (
                Verification.IsDecimalMagnitudeBelow(text, Our.Constants.XsDoubleOverflowThreshold));
        }  // public static bool IsXsDouble

