        /// <summary>
        /// Check that the <paramref name="value" /> conforms to its <paramref name="valueType" />.
        /// </summary>
        /// <param name="value">
        /// which needs to conform
        /// </param>
        /// <param name="value_type">
        /// pre-defined value type
        /// </param>
        /// <returns>
        /// True if the <paramref name="value" /> conforms
        /// </returns>
        public static bool ValueConsistentWithXsdType(
            string value,
            DataTypeDefXsd valueType
        )
        {
            switch (valueType)
            {
                case DataTypeDefXsd.AnyUri:
                    return Verification.MatchesXsAnyUri(value);
                case DataTypeDefXsd.Base64Binary:
                    return Verification.MatchesXsBase64Binary(value);
                case DataTypeDefXsd.Boolean:
                    return Verification.MatchesXsBoolean(value);
                case DataTypeDefXsd.Byte:
                    return Verification.IsXsByte(value);
                case DataTypeDefXsd.Date:
                    return Verification.IsXsDate(value);
                case DataTypeDefXsd.DateTime:
                    return Verification.IsXsDateTime(value);
                case DataTypeDefXsd.Decimal:
                    return Verification.MatchesXsDecimal(value);
                case DataTypeDefXsd.Double:
                    return Verification.IsXsDouble(value);
                case DataTypeDefXsd.Duration:
                    return Verification.MatchesXsDuration(value);
                case DataTypeDefXsd.Float:
                    return Verification.IsXsFloat(value);
                case DataTypeDefXsd.GDay:
                    return Verification.MatchesXsGDay(value);
                case DataTypeDefXsd.GMonth:
                    return Verification.MatchesXsGMonth(value);
                case DataTypeDefXsd.GMonthDay:
                    return Verification.IsXsGMonthDay(value);
                case DataTypeDefXsd.GYear:
                    return Verification.MatchesXsGYear(value);
                case DataTypeDefXsd.GYearMonth:
                    return Verification.MatchesXsGYearMonth(value);
                case DataTypeDefXsd.HexBinary:
                    return Verification.MatchesXsHexBinary(value);
                case DataTypeDefXsd.Int:
                    return Verification.IsXsInt(value);
                case DataTypeDefXsd.Integer:
                    return Verification.MatchesXsInteger(value);
                case DataTypeDefXsd.Long:
                    return Verification.IsXsLong(value);
                case DataTypeDefXsd.NegativeInteger:
                    return Verification.MatchesXsNegativeInteger(value);
                case DataTypeDefXsd.NonNegativeInteger:
                    return Verification.MatchesXsNonNegativeInteger(value);
                case DataTypeDefXsd.NonPositiveInteger:
                    return Verification.MatchesXsNonPositiveInteger(value);
                case DataTypeDefXsd.PositiveInteger:
                    return Verification.MatchesXsPositiveInteger(value);
                case DataTypeDefXsd.Short:
                    return Verification.IsXsShort(value);
                case DataTypeDefXsd.String:
                    return Verification.MatchesXsString(value);
                case DataTypeDefXsd.Time:
                    return Verification.MatchesXsTime(value);
                case DataTypeDefXsd.UnsignedByte:
                    return Verification.IsXsUnsignedByte(value);
                case DataTypeDefXsd.UnsignedInt:
                    return Verification.IsXsUnsignedInt(value);
                case DataTypeDefXsd.UnsignedLong:
                    return Verification.IsXsUnsignedLong(value);
                case DataTypeDefXsd.UnsignedShort:
                    return Verification.IsXsUnsignedShort(value);
            }
            return false;
        }  // public static bool ValueConsistentWithXsdType

        /// <summary>
        /// Check that the target of the model reference matches the <paramref name="expectedType" />.
        /// </summary>
        public static bool IsModelReferenceTo(
            IReference reference,
            KeyTypes expectedType
        )
        {
            return reference.Type == ReferenceTypes.ModelReference
            && reference.Keys.Count != 0
            && reference.Keys[^1].Type == expectedType;
        }  // public static bool IsModelReferenceTo

        /// <summary>
        /// Check that the target of the reference matches a <see cref="Our.Constants.AasReferables" />.
        /// </summary>
        public static bool IsModelReferenceToReferable(
            IReference reference
        )
        {
            return reference.Type == ReferenceTypes.ModelReference
            && reference.Keys.Count != 0
            && Our.Constants.AasReferables.Contains(reference.Keys[^1].Type);
        }  // public static bool IsModelReferenceToReferable

        /// <summary>
        /// Check that the <see cref="Our.IReferable.IdShort" />'s among the <paramref name="referables" /> are
        /// unique in their namespace.
        /// </summary>
        /// <remarks>
        /// The argument referables is declared as the covariant IReadOnlyList&lt;IReferable&gt; instead of the invariant List&lt;IReferable&gt; so that the lists of the descendants of IReferable can be passed without a copy.
        /// </remarks>
        public static bool IdShortsAreUnique(
            IReadOnlyList<IReferable> referables
        )
        {
            HashSet<string> idShortSet = new HashSet<string>();
            foreach (var referable in referables)
            {
                var idShort = referable.IdShort;
                if (idShort == null)
                {
                    continue;
                }
                if (idShortSet.Contains(idShort))
                {
                    return false;
                }
                idShortSet.Add(idShort);
            }
            return true;
        }  // public static bool IdShortsAreUnique

        /// <summary>
        /// Collect the <see cref="Our.IReferable.IdShort" />'s of the <paramref name="variables" /> values.
        /// </summary>
        /// <param name="variables">
        /// Operation variables whose ID-shorts we collect
        /// </param>
        /// <param name="id_short_set">
        /// ID-shorts observed so far, extended in place
        /// </param>
        /// <returns>
        /// False if an ID-short has been already observed
        /// </returns>
        internal static bool CollectUniqueIdShortsOfVariables(
            List<IOperationVariable>? variables,
            HashSet<string> idShortSet
        )
        {
            if (variables == null)
            {
                return true;
            }
            foreach (var variable in variables)
            {
                var idShort = variable.Value.IdShort;
                if (idShort == null)
                {
                    continue;
                }
                if (idShortSet.Contains(idShort))
                {
                    return false;
                }
                idShortSet.Add(idShort);
            }
            return true;
        }  // internal static bool CollectUniqueIdShortsOfVariables

        /// <summary>
        /// Check that the <see cref="Our.IReferable.IdShort" />'s among all the
        /// <paramref name="inputVariables" />, <paramref name="outputVariables" />
        /// and <paramref name="inoutputVariables" /> are unique.
        /// </summary>
        public static bool IdShortsOfVariablesAreUnique(
            List<IOperationVariable>? inputVariables,
            List<IOperationVariable>? outputVariables,
            List<IOperationVariable>? inoutputVariables
        )
        {
            HashSet<string> idShortSet = new HashSet<string>();
            return Verification.CollectUniqueIdShortsOfVariables(inputVariables, idShortSet)
            && Verification.CollectUniqueIdShortsOfVariables(outputVariables, idShortSet)
            && Verification.CollectUniqueIdShortsOfVariables(inoutputVariables, idShortSet);
        }  // public static bool IdShortsOfVariablesAreUnique

        [CodeAnalysis.SuppressMessage("ReSharper", "InconsistentNaming")]
        [CodeAnalysis.SuppressMessageAttribute("ReSharper", "IdentifierTypo")]
        [CodeAnalysis.SuppressMessage("ReSharper", "StringLiteralTypo")]
        private static Regex _constructSpecificAssetIdNameMatchesGlobalAssetId()
        {
            var pattern = "^[gG][lL][oO][bB][aA][lL][aA][sS][sS][eE][tT][iI][dD]$";

            return new Regex(pattern);
        }

        private static readonly Regex RegexSpecificAssetIdNameMatchesGlobalAssetId = _constructSpecificAssetIdNameMatchesGlobalAssetId();

        /// <summary>
        /// Check whether <paramref name="name" /> is the reserved global asset ID key.
        /// </summary>
        public static bool SpecificAssetIdNameMatchesGlobalAssetId(string name)
        {
            return RegexSpecificAssetIdNameMatchesGlobalAssetId.IsMatch(name);
        }

        /// <summary>
        /// Check whether <paramref name="element" /> or its descendants have template qualifiers.
        /// </summary>
        public static bool SubmodelElementHasTemplateQualifierInTree(
            ISubmodelElement element
        )
        {
            if (
                (element.Qualifiers != null)
                && (
                    element.Qualifiers.Any(
                        qualifier => qualifier.KindOrDefault() == QualifierKind.TemplateQualifier)
                )
            )
            {
                return true;
            }
            if (element is Our.ISubmodelElementList)
            {
                return (((Our.ISubmodelElementList)element).Value != null)
                && (
                    ((Our.ISubmodelElementList)element).Value.Any(
                        child => Verification.SubmodelElementHasTemplateQualifierInTree(child))
                );
            }
            if (element is Our.ISubmodelElementCollection)
            {
                return (((Our.ISubmodelElementCollection)element).Value != null)
                && (
                    ((Our.ISubmodelElementCollection)element).Value.Any(
                        child => Verification.SubmodelElementHasTemplateQualifierInTree(child))
                );
            }
            if (element is Our.IEntity)
            {
                return (((Our.IEntity)element).Statements != null)
                && (
                    ((Our.IEntity)element).Statements.Any(
                        child => Verification.SubmodelElementHasTemplateQualifierInTree(child))
                );
            }
            if (element is Our.IAnnotatedRelationshipElement)
            {
                return (((Our.IAnnotatedRelationshipElement)element).Annotations != null)
                && (
                    ((Our.IAnnotatedRelationshipElement)element).Annotations.Any(
                        child => Verification.SubmodelElementHasTemplateQualifierInTree(child))
                );
            }
            if (element is Our.IOperation)
            {
            }
            return false;
        }  // public static bool SubmodelElementHasTemplateQualifierInTree

        /// <summary>
        /// Check that <paramref name="elements" /> have no template qualifiers in their trees.
        /// </summary>
        /// <remarks>
        /// The argument elements is declared as the covariant IReadOnlyList&lt;ISubmodelElement&gt; instead of the invariant List&lt;ISubmodelElement&gt; so that the lists of the descendants of ISubmodelElement can be passed without a copy.
        /// </remarks>
        public static bool SubmodelElementsHaveNoTemplateQualifiers(
            IReadOnlyList<ISubmodelElement> elements
        )
        {
            return elements.All(
                element => !Verification.SubmodelElementHasTemplateQualifierInTree(element));
        }  // public static bool SubmodelElementsHaveNoTemplateQualifiers

        /// <summary>
        /// Recursively check that submodel element lists have exactly one child.
        /// </summary>
        public static bool SubmodelElementListsHaveExactlyOneElementInTree(
            ISubmodelElement element
        )
        {
            if (element is Our.ISubmodelElementList)
            {
                return (((Our.ISubmodelElementList)element).Value != null)
                && ((Our.ISubmodelElementList)element).Value.Count == 1
                && (
                    ((Our.ISubmodelElementList)element).Value.All(
                        child => Verification.SubmodelElementListsHaveExactlyOneElementInTree(child))
                );
            }
            if (element is Our.ISubmodelElementCollection)
            {
                return (((Our.ISubmodelElementCollection)element).Value == null)
                || (
                    ((Our.ISubmodelElementCollection)element).Value.All(
                        child => Verification.SubmodelElementListsHaveExactlyOneElementInTree(child))
                );
            }
            if (element is Our.IEntity)
            {
                return (((Our.IEntity)element).Statements == null)
                || (
                    ((Our.IEntity)element).Statements.All(
                        child => Verification.SubmodelElementListsHaveExactlyOneElementInTree(child))
                );
            }
            if (element is Our.IAnnotatedRelationshipElement)
            {
                return (((Our.IAnnotatedRelationshipElement)element).Annotations == null)
                || (
                    ((Our.IAnnotatedRelationshipElement)element).Annotations.All(
                        child => Verification.SubmodelElementListsHaveExactlyOneElementInTree(child))
                );
            }
            return true;
        }  // public static bool SubmodelElementListsHaveExactlyOneElementInTree

        /// <summary>
        /// Check that all submodel element lists among <paramref name="elements" /> have one item.
        /// </summary>
        /// <remarks>
        /// The argument elements is declared as the covariant IReadOnlyList&lt;ISubmodelElement&gt; instead of the invariant List&lt;ISubmodelElement&gt; so that the lists of the descendants of ISubmodelElement can be passed without a copy.
        /// </remarks>
        public static bool SubmodelElementListsInSubmodelElementsHaveExactlyOneElement(
            IReadOnlyList<ISubmodelElement> elements
        )
        {
            return elements.All(
                element => Verification.SubmodelElementListsHaveExactlyOneElementInTree(element));
        }  // public static bool SubmodelElementListsInSubmodelElementsHaveExactlyOneElement

        /// <summary>
        /// Check that submodel element lists in operation variables have one item.
        /// </summary>
        public static bool SubmodelElementListsInOperationVariablesHaveExactlyOneElement(
            List<IOperationVariable>? inputVariables,
            List<IOperationVariable>? outputVariables,
            List<IOperationVariable>? inoutputVariables
        )
        {
            return (
                (inputVariables == null)
                || (
                    inputVariables.All(
                        variable => Verification.SubmodelElementListsHaveExactlyOneElementInTree(variable.Value))
                )
            )
            && (
                (outputVariables == null)
                || (
                    outputVariables.All(
                        variable => Verification.SubmodelElementListsHaveExactlyOneElementInTree(variable.Value))
                )
            )
            && (
                (inoutputVariables == null)
                || (
                    inoutputVariables.All(
                        variable => Verification.SubmodelElementListsHaveExactlyOneElementInTree(variable.Value))
                )
            );
        }  // public static bool SubmodelElementListsInOperationVariablesHaveExactlyOneElement

        /// <summary>
        /// Check that the extension names are unique.
        /// </summary>
        public static bool ExtensionNamesAreUnique(
            List<IExtension> extensions
        )
        {
            HashSet<string> nameSet = new HashSet<string>();
            foreach (var extension in extensions)
            {
                if (nameSet.Contains(extension.Name))
                {
                    return false;
                }
                nameSet.Add(extension.Name);
            }
            return true;
        }  // public static bool ExtensionNamesAreUnique

        /// <summary>
        /// Check that all semantic IDs are identical, if specified.
        /// </summary>
        /// <remarks>
        /// The argument elements is declared as the covariant IReadOnlyList&lt;ISubmodelElement&gt; instead of the invariant List&lt;ISubmodelElement&gt; so that the lists of the descendants of ISubmodelElement can be passed without a copy.
        /// </remarks>
        public static bool SubmodelElementsHaveIdenticalSemanticIds(
            IReadOnlyList<ISubmodelElement> elements
        )
        {
            Our.IReference? thatSemanticId = null;
            foreach (var element in elements)
            {
                var thisSemanticId = element.SemanticId;
                if (thisSemanticId == null)
                {
                    continue;
                }
                if (thatSemanticId == null)
                {
                    thatSemanticId = thisSemanticId;
                }
                else if (!Verification.ReferenceKeyValuesEqual(thatSemanticId, thisSemanticId))
                {
                    return false;
                }
            }
            return true;
        }  // public static bool SubmodelElementsHaveIdenticalSemanticIds

        /// <summary>
        /// Check that the run-time type of the <paramref name="element" /> coincides with
        /// <paramref name="elementType" />.
        /// </summary>
        public static bool SubmodelElementIsOfType(
            ISubmodelElement element,
            AasSubmodelElements elementType
        )
        {
            switch (elementType)
            {
                case AasSubmodelElements.AnnotatedRelationshipElement:
                    return element is Our.IAnnotatedRelationshipElement;
                case AasSubmodelElements.BasicEventElement:
                    return element is Our.IBasicEventElement;
                case AasSubmodelElements.Blob:
                    return element is Our.IBlob;
                case AasSubmodelElements.Capability:
                    return element is Our.ICapability;
                case AasSubmodelElements.DataElement:
                    return element is Our.IDataElement;
                case AasSubmodelElements.Entity:
                    return element is Our.IEntity;
                case AasSubmodelElements.EventElement:
                    return element is Our.IEventElement;
                case AasSubmodelElements.File:
                    return element is Our.IFile;
                case AasSubmodelElements.MultiLanguageProperty:
                    return element is Our.IMultiLanguageProperty;
                case AasSubmodelElements.Operation:
                    return element is Our.IOperation;
                case AasSubmodelElements.Property:
                    return element is Our.IProperty;
                case AasSubmodelElements.Range:
                    return element is Our.IRange;
                case AasSubmodelElements.ReferenceElement:
                    return element is Our.IReferenceElement;
                case AasSubmodelElements.RelationshipElement:
                    return element is Our.IRelationshipElement;
                case AasSubmodelElements.SubmodelElement:
                    return true;
                case AasSubmodelElements.SubmodelElementList:
                    return element is Our.ISubmodelElementList;
                case AasSubmodelElements.SubmodelElementCollection:
                    return element is Our.ISubmodelElementCollection;
            }
            return false;
        }  // public static bool SubmodelElementIsOfType

        /// <summary>
        /// Check that all the <paramref name="elements" /> have the <paramref name="valueType" />.
        /// </summary>
        /// <remarks>
        /// The argument elements is declared as the covariant IReadOnlyList&lt;ISubmodelElement&gt; instead of the invariant List&lt;ISubmodelElement&gt; so that the lists of the descendants of ISubmodelElement can be passed without a copy.
        /// </remarks>
        public static bool PropertiesOrRangesHaveValueType(
            IReadOnlyList<ISubmodelElement> elements,
            DataTypeDefXsd valueType
        )
        {
            foreach (var element in elements)
            {
                if (
                    element is Our.IProperty
                    && ((Our.IProperty)element).ValueType != valueType
                )
                {
                    return false;
                }
                if (
                    element is Our.IRange
                    && ((Our.IRange)element).ValueType != valueType
                )
                {
                    return false;
                }
            }
            return true;
        }  // public static bool PropertiesOrRangesHaveValueType

        /// <summary>
        /// Check that the two references are equal by comparing their key values.
        /// </summary>
        public static bool ReferenceKeyValuesEqual(
            IReference that,
            IReference other
        )
        {
            if (that.Keys.Count != other.Keys.Count)
            {
                return false;
            }
            for (int i = 0; i < that.Keys.Count; i++)
            {
                if (that.Keys[i].Value != other.Keys[i].Value)
                {
                    return false;
                }
            }
            return true;
        }  // public static bool ReferenceKeyValuesEqual

