        /// <summary>
        /// Check that the <see cref="Our.DataSpecificationIec61360.Definition" /> is defined
        /// for all data specifications whose content is given as IEC 61360 at least in English.
        /// </summary>
        public static bool DataSpecificationIec61360sHaveDefinitionAtLeastInEnglish(
            List<IEmbeddedDataSpecification> embeddedDataSpecifications
        )
        {
            foreach (var dataSpecification in embeddedDataSpecifications)
            {
                var content = dataSpecification.DataSpecificationContent;
                if (!(content is Our.IDataSpecificationIec61360))
                {
                    continue;
                }
                var definition = (
                    ((Our.IDataSpecificationIec61360)content).Definition);
                if (definition == null)
                {
                    return false;
                }
                if (
                    !(definition.Any(
                        langString => Verification.IsBcp47ForEnglish(langString.Language)))
                )
                {
                    return false;
                }
            }
            return true;
        }  // public static bool DataSpecificationIec61360sHaveDefinitionAtLeastInEnglish

