        /// </param>
        /// <param name="value_type">
        /// One of <c>string</c>, <c>number</c>, <c>hex</c>, <c>boolean</c>, <c>date_time</c>
        /// or <c>time</c>
        /// </param>
        /// <returns>
        /// True if <paramref name="value" /> can be used as <paramref name="valueType" />
        /// </returns>
        internal static bool CanBeOfType(
            Value value,
            string valueType
        )
        {
            if (value.Underlying is Our.IFieldOperand)
            {
                return true;
            }
            if (value.Underlying is Our.IAttributeOperand)
            {
                if (valueType == "string")
                {
                    return true;
                }
                var attribute = (
                    ((Our.IAttributeOperand)value.Underlying).Attribute);
                return valueType == "date_time"
                && attribute.Underlying is Our.IGlobalAttribute
                && (
                    ((Our.IGlobalAttribute)attribute.Underlying).Kind == GlobalAttributeKind.LocalNow
                    || ((Our.IGlobalAttribute)attribute.Underlying).Kind == GlobalAttributeKind.UtcNow
                    || ((Our.IGlobalAttribute)attribute.Underlying).Kind == GlobalAttributeKind.ClientNow
                );
            }
            if ((value.Underlying is Our.IStringLiteral || value.Underlying is Our.IStringCast))
            {
                return valueType == "string";
            }
            if ((value.Underlying is Our.INumberLiteral || value.Underlying is Our.INumberCast || value.Underlying is Our.IDayOfWeek || value.Underlying is Our.IDayOfMonth || value.Underlying is Our.IMonth || value.Underlying is Our.IYear))
            {
                return valueType == "number";
            }
            if ((value.Underlying is Our.IHexLiteral || value.Underlying is Our.IHexCast))
            {
                return valueType == "hex";
            }
            if ((value.Underlying is Our.IBooleanLiteral || value.Underlying is Our.IBooleanCast))
            {
                return valueType == "boolean";
            }
            if ((value.Underlying is Our.IDateTimeLiteral || value.Underlying is Our.IDateTimeCast))
            {
                return valueType == "date_time";
            }
            if ((value.Underlying is Our.ITimeLiteral || value.Underlying is Our.ITimeCast))
            {
                return valueType == "time";
            }
            return false;
        }  // internal static bool CanBeOfType

        /// <summary>
        /// Check that <paramref name="left" /> and <paramref name="right" /> can be compared for
        /// (in)equality.
        /// </summary>
        /// <remarks>
        /// <para>
        /// Following the normative JSON schema of the query language, the two operands
        /// need to be of the same type: a string, a number, a hexadecimal, a boolean,
        /// a date-time or a time. A field is implicitly cast to the type of the other
        /// operand, and can hence be compared with an operand of any type. A global
        /// attribute giving a date and time (<c>LOCALNOW</c>, <c>UTCNOW</c> or <c>CLIENTNOW</c>)
        /// can be used both as a string and as a date-time.
        /// </para>
        /// <para>
        /// See:
        /// https://industrialdigitaltwin.io/aas-specifications/IDTA-01002/v3.2/query-language.html#_json_schema
        /// </para>
        /// </remarks>
        /// <param name="left">
        /// First operand of the comparison
        /// </param>
        /// <param name="right">
        /// Second operand of the comparison
        /// </param>
        /// <returns>
        /// True if the operands can be compared for (in)equality
        /// </returns>
        public static bool AreEqualityComparable(
            Value left,
            Value right
        )
        {
            return (
                Verification.CanBeOfType(left, "string")
                && Verification.CanBeOfType(right, "string")
            )
            || (
                Verification.CanBeOfType(left, "number")
                && Verification.CanBeOfType(right, "number")
            )
            || (
                Verification.CanBeOfType(left, "hex")
                && Verification.CanBeOfType(right, "hex")
            )
            || (
                Verification.CanBeOfType(left, "boolean")
                && Verification.CanBeOfType(right, "boolean")
            )
            || (
                Verification.CanBeOfType(left, "date_time")
                && Verification.CanBeOfType(right, "date_time")
            )
            || (
                Verification.CanBeOfType(left, "time")
                && Verification.CanBeOfType(right, "time")
            );
        }  // public static bool AreEqualityComparable

        /// <summary>
        /// Check that <paramref name="left" /> and <paramref name="right" /> can be compared by order.
        /// </summary>
        /// <remarks>
        /// <para>
        /// The operands need to be comparable for (in)equality (see
        /// <c>are_equality_comparable</c>), but booleans can not be ordered.
        /// </para>
        /// <para>
        /// See:
        /// https://industrialdigitaltwin.io/aas-specifications/IDTA-01002/v3.2/query-language.html#_json_schema
        /// </para>
        /// </remarks>
        /// <param name="left">
        /// First operand of the comparison
        /// </param>
        /// <param name="right">
        /// Second operand of the comparison
        /// </param>
        /// <returns>
        /// True if the operands can be compared by order
        /// </returns>
        public static bool AreOrderComparable(
            Value left,
            Value right
        )
        {
            return Verification.AreEqualityComparable(left, right)
            && (!((left.Underlying is Our.IBooleanLiteral || left.Underlying is Our.IBooleanCast)))
            && (!((right.Underlying is Our.IBooleanLiteral || right.Underlying is Our.IBooleanCast)));
        }  // public static bool AreOrderComparable

