        [CodeAnalysis.SuppressMessage("ReSharper", "InconsistentNaming")]
        private static readonly Verification.Transformer _transformer = (
            new Verification.Transformer());

        private class Transformer
            : Visitation.AbstractTransformer<IEnumerable<Reporting.Error>>
        {
            [CodeAnalysis.SuppressMessage("ReSharper", "NegativeEqualityExpression")]
            public override IEnumerable<Reporting.Error> TransformExtension(
                Our.IExtension that
            )
            {
                if (!(
                    !(that.SupplementalSemanticIds != null)
                    || (that.SupplementalSemanticIds.Count >= 1)))
                {
                    yield return new Reporting.Error(
                        "Invariant violated:\n" +
                        "Supplemental semantic IDs must be either not set or have at " +
                        "least one item.");
                }

                if (!(
                    !(that.SupplementalSemanticIds != null)
                    || (that.SemanticId != null)))
                {
                    yield return new Reporting.Error(
                        "Invariant violated:\n" +
                        "Constraint AASd-118: If there are supplemental semantic IDs " +
                        "defined then there shall be also a main semantic ID.");
                }

                if (!(
                    !(that.RefersTo != null)
                    || (that.RefersTo.Count >= 1)))
                {
                    yield return new Reporting.Error(
                        "Invariant violated:\n" +
                        "Refers-to must be either not set or have at least one item.");
                }

                if (!(
                    !(that.Value != null)
                    || Verification.ValueConsistentWithXsdType(that.Value, that.ValueTypeOrDefault())))
                {
                    yield return new Reporting.Error(
                        "Invariant violated:\n" +
                        "The value must match the value type.");
                }

                if (that.SemanticId != null)
                {
                    foreach (var error in Verification.Verify(that.SemanticId))
                    {
                        error.PrependSegment(
                            new Reporting.NameSegment("semanticId"));
                        yield return error;
                    }
                }

                if (that.SupplementalSemanticIds != null)
                {
                    foreach (
                        var error in Verification.Verify_ListOf_IReference(
                            that.SupplementalSemanticIds))
                    {
                        error.PrependSegment(
                            new Reporting.NameSegment("supplementalSemanticIds"));
                        yield return error;
                    }
                }

                foreach (var error in Verification.VerifyNameType(that.Name))
                {
                    error.PrependSegment(
                        new Reporting.NameSegment("name"));
                    yield return error;
                }

                if (that.ValueType.HasValue)
                {
                    foreach (
                        var error in Verification.VerifyDataTypeDefXsd(
                            that.ValueType.Value))
                    {
                        error.PrependSegment(
                            new Reporting.NameSegment("valueType"));
                        yield return error;
                    }
                }

                if (that.Value != null)
                {
                    foreach (var error in Verification.VerifyValueDataType(that.Value))
                    {
                        error.PrependSegment(
                            new Reporting.NameSegment("value"));
                        yield return error;
                    }
                }

                if (that.RefersTo != null)
                {
                    foreach (
                        var error in Verification.Verify_ListOf_IReference(
                            that.RefersTo))
                    {
                        error.PrependSegment(
                            new Reporting.NameSegment("refersTo"));
                        yield return error;
                    }
                }
            }

            [CodeAnalysis.SuppressMessage("ReSharper", "NegativeEqualityExpression")]
            public override IEnumerable<Reporting.Error> TransformAdministrativeInformation(
                Our.IAdministrativeInformation that
            )
            {
                if (!(
                    !(that.EmbeddedDataSpecifications != null)
                    || (that.EmbeddedDataSpecifications.Count >= 1)))
                {
                    yield return new Reporting.Error(
                        "Invariant violated:\n" +
                        "Embedded data specifications must be either not set or have " +
                        "at least one item.");
                }

                if (!(
                    !(
                        (that.CreatedAt != null)
                        && (that.UpdatedAt != null)
                    )
                    || Verification.DateTimeUtcLessOrInvalid(that.CreatedAt, that.UpdatedAt)))
                {
                    yield return new Reporting.Error(
                        "Invariant violated:\n" +
                        "Created-at must be before updated-at.");
                }

                if (!(
                    !(that.Revision != null)
                    || (that.Version != null)))
                {
                    yield return new Reporting.Error(
                        "Invariant violated:\n" +
                        "Constraint AASd-005: If version is not specified, revision " +
                        "shall also be unspecified. This means that a revision " +
